#################################################################
#    Rubrics and Scoring Strategies
#################################################################

ea:Rubric
    a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    skos:altLabel "Scoring Guide"@en ;
    rdfs:label "Rubric"@en .

ea:ScoringStrategy
    a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Scoring Strategy"@en ;
    owl:disjointUnionOf (
        ea:HolisticScoring
        ea:AnalyticScoring
        ea:DevelopmentalScoring
        ea:TraitInformedScoring
    ) .

ea:HolisticScoring a owl:Class ; rdfs:subClassOf ea:ScoringStrategy ; rdfs:label "Holistic Scoring"@en .
ea:AnalyticScoring a owl:Class ; rdfs:subClassOf ea:ScoringStrategy ; rdfs:label "Analytic Scoring"@en .
ea:DevelopmentalScoring a owl:Class ; rdfs:subClassOf ea:ScoringStrategy ; rdfs:label "Developmental Scoring"@en .
ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:ScoringStrategy ; rdfs:label "Trait-Informed Scoring"@en .

ea:HolisticRubric
    a owl:Class ;
    rdfs:subClassOf ea:Rubric ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Rubric
            [ a owl:Restriction ; owl:onProperty ea:hasScoringStrategy ; owl:someValuesFrom ea:HolisticScoring ]
        )
    ] ;
    rdfs:label "Holistic Rubric"@en .

ea:AnalyticRubric
    a owl:Class ;
    rdfs:subClassOf ea:Rubric ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Rubric
            [ a owl:Restriction ; owl:onProperty ea:hasScoringStrategy ; owl:someValuesFrom ea:AnalyticScoring ]
        )
    ] ;
    rdfs:label "Analytic Rubric"@en .

ea:DevelopmentalRubric
    a owl:Class ;
    rdfs:subClassOf ea:Rubric ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Rubric
            [ a owl:Restriction ; owl:onProperty ea:hasScoringStrategy ; owl:someValuesFrom ea:DevelopmentalScoring ]
        )
    ] ;
    rdfs:label "Developmental Rubric"@en .

